#!/usr/bin/env python3
"""CSV Insights: filter and aggregate RFC-style CSV files."""

from __future__ import annotations

import argparse
import csv
import json
import sys
from collections.abc import Sequence
from decimal import Decimal, InvalidOperation, localcontext
from pathlib import Path


class CsvInsightsError(Exception):
    """An input or usage error that is safe to show to the user."""


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description="Filter CSV rows and optionally calculate grouped sums/averages."
    )
    parser.add_argument("input", metavar="INPUT.csv", help="CSV file to analyze")
    parser.add_argument(
        "--where",
        action="append",
        default=[],
        metavar="COLUMN=VALUE",
        help="keep rows whose column exactly equals value (repeatable)",
    )
    parser.add_argument("--group-by", metavar="COLUMN", help="column used to group results")
    parser.add_argument("--sum", dest="sum_column", metavar="COLUMN", help="column to sum")
    parser.add_argument("--avg", dest="avg_column", metavar="COLUMN", help="column to average")
    parser.add_argument(
        "--output", choices=("json", "csv"), default="json", help="output format (default: json)"
    )
    return parser


def parse_filters(raw_filters: Sequence[str]) -> list[tuple[str, str]]:
    filters: list[tuple[str, str]] = []
    for expression in raw_filters:
        if "=" not in expression:
            raise CsvInsightsError(
                f"malformed filter {expression!r}: expected COLUMN=VALUE"
            )
        column, value = expression.split("=", 1)
        if not column:
            raise CsvInsightsError(
                f"malformed filter {expression!r}: column name must not be empty"
            )
        filters.append((column, value))
    return filters


def read_csv(path: str) -> tuple[list[str], list[tuple[int, list[str]]]]:
    try:
        with Path(path).open("r", encoding="utf-8", newline="") as stream:
            reader = csv.reader(stream, strict=True)
            try:
                header = next(reader)
            except StopIteration as exc:
                raise CsvInsightsError("input is empty: a header row is required") from exc

            if not header or any(name == "" for name in header):
                raise CsvInsightsError("headers must be non-empty")

            duplicate = next(
                (name for position, name in enumerate(header) if name in header[:position]),
                None,
            )
            if duplicate is not None:
                raise CsvInsightsError(f"headers must be unique; duplicate column {duplicate!r}")

            rows: list[tuple[int, list[str]]] = []
            for row_number, row in enumerate(reader, start=2):
                if len(row) != len(header):
                    raise CsvInsightsError(
                        f"row {row_number} has {len(row)} fields; expected {len(header)}"
                    )
                rows.append((row_number, row))
            return header, rows
    except CsvInsightsError:
        raise
    except csv.Error as exc:
        raise CsvInsightsError(f"malformed CSV: {exc}") from exc
    except UnicodeError as exc:
        raise CsvInsightsError(f"input is not valid UTF-8: {exc}") from exc
    except OSError as exc:
        raise CsvInsightsError(f"cannot read {path!r}: {exc}") from exc


def require_column(header: Sequence[str], column: str, option: str) -> int:
    try:
        return header.index(column)
    except ValueError as exc:
        raise CsvInsightsError(f"unknown column {column!r} for {option}") from exc


def decimal_value(value: str, row_number: int, column: str) -> Decimal:
    if value == "":
        raise CsvInsightsError(f"invalid numeric value at row {row_number}, column {column!r}: blank")
    try:
        number = Decimal(value)
    except InvalidOperation as exc:
        raise CsvInsightsError(
            f"invalid numeric value at row {row_number}, column {column!r}: {value!r}"
        ) from exc
    if not number.is_finite():
        raise CsvInsightsError(
            f"invalid numeric value at row {row_number}, column {column!r}: {value!r}"
        )
    return number


def exact_sum(values: Sequence[Decimal]) -> Decimal:
    """Sum finite Decimals without losing input digits to the default context."""
    if not values:
        return Decimal(0)
    nonzero = [value for value in values if value]
    if not nonzero:
        return Decimal(0)
    lowest_exponent = min(value.as_tuple().exponent for value in nonzero)
    highest_adjusted = max(value.adjusted() for value in nonzero)
    precision = max(28, highest_adjusted - lowest_exponent + len(str(len(values))) + 2)
    with localcontext() as context:
        context.prec = precision
        return sum(values, Decimal(0))


def format_decimal(value: Decimal) -> str:
    text = format(value, "f")
    if "." in text:
        text = text.rstrip("0").rstrip(".")
    return "0" if text in ("", "-0") else text


def process(
    header: list[str],
    numbered_rows: list[tuple[int, list[str]]],
    filters: Sequence[tuple[str, str]],
    group_column: str | None,
    sum_column: str | None,
    avg_column: str | None,
) -> tuple[list[str], list[list[str]]]:
    filter_indexes = [
        (require_column(header, column, "--where"), expected)
        for column, expected in filters
    ]
    filtered = [
        (row_number, row)
        for row_number, row in numbered_rows
        if all(row[index] == expected for index, expected in filter_indexes)
    ]

    if sum_column is None and avg_column is None:
        return header, [row for _, row in filtered]
    if group_column is None:
        raise CsvInsightsError("--sum and --avg require --group-by")

    group_index = require_column(header, group_column, "--group-by")
    sum_index = require_column(header, sum_column, "--sum") if sum_column else None
    avg_index = require_column(header, avg_column, "--avg") if avg_column else None
    groups: dict[str, dict[str, list[Decimal]]] = {}

    for row_number, row in filtered:
        group = groups.setdefault(row[group_index], {"sum": [], "avg": []})
        if sum_index is not None:
            group["sum"].append(decimal_value(row[sum_index], row_number, sum_column))
        if avg_index is not None:
            group["avg"].append(decimal_value(row[avg_index], row_number, avg_column))

    output_header = [group_column]
    if sum_column is not None:
        output_header.append(f"sum_{sum_column}")
    if avg_column is not None:
        output_header.append(f"avg_{avg_column}")

    output_rows: list[list[str]] = []
    for group_value in sorted(groups):
        result = [group_value]
        if sum_column is not None:
            result.append(format_decimal(exact_sum(groups[group_value]["sum"])))
        if avg_column is not None:
            values = groups[group_value]["avg"]
            result.append(format_decimal(exact_sum(values) / Decimal(len(values))))
        output_rows.append(result)
    return output_header, output_rows


def emit(output_format: str, header: Sequence[str], rows: Sequence[Sequence[str]]) -> None:
    if output_format == "csv":
        writer = csv.writer(sys.stdout, lineterminator="\r\n")
        writer.writerow(header)
        writer.writerows(rows)
        return
    objects = [dict(zip(header, row)) for row in rows]
    json.dump(objects, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")


def main(argv: Sequence[str] | None = None) -> int:
    parser = build_parser()
    args = parser.parse_args(argv)
    try:
        filters = parse_filters(args.where)
        if (args.sum_column or args.avg_column) and not args.group_by:
            raise CsvInsightsError("--sum and --avg require --group-by")
        header, rows = read_csv(args.input)
        output_header, output_rows = process(
            header,
            rows,
            filters,
            args.group_by,
            args.sum_column,
            args.avg_column,
        )
        emit(args.output, output_header, output_rows)
    except CsvInsightsError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 2
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
